    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    blocks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key or not blocks:
        return out

    min_r = min(r for r, _, _ in blocks)
    max_r = max(r for r, _, _ in blocks)
    min_c = min(c for _, c in blocks)
    max_c = max(c for _, c in blocks)

    # Each large 8-cell is a square tile; the common run length gives its side.
    runs = []
    for r in range(h):
        lengths = []
        run = 0
        for c in range(w):
            if grid[r][c] == 8:
                run += 1
            elif run:
                lengths.append(run)
                run = 0
        if run:
            lengths.append(run)
        runs.extend(lengths)
    for c in range(w):
        run = 0
        for r in range(h):
            if grid[r][c] == 8:
                run += 1
            elif run:
                runs.append(run)
                run = 0
        if run:
            runs.append(run)
    tile = reduce(gcd, runs)

    kr0 = min(r for r, _, _ in key)
    kr1 = max(r for r, _, _ in key)
    kc0 = min(c for _, c, _ in key)
    # Rotate the colored pixel-pattern 90 degrees clockwise.
